
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_rational_p_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_rational_p", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([8.102812067595910e+01, 7.743771442309378e+01, 7.253573094398770e+01, 6.599459380128401e+01, 5.754932417990914e+01, 4.715206714092974e+01, 3.520506771037056e+01, 2.280781323532161e+01, 1.182947316210947e+01, 4.461489560065003e+00, 1.799004024739745e+00, 2.069239436513081e+00, 1.738387608064816e+00, 9.743634396153904e-01, 3.472137127526597e-01, 5.892259196215960e-02, 2.504438184503570e-03, 1.394012423653002e-05, 6.610595569578825e-09, 1.213121930282664e-13]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


